        let ResourceState::Valid(state) = &self.state else {
            return Err(InvalidResourceError(self.error_ident()));
        };
        Ok(&state.layout)
    }

    pub(crate) fn check_valid(&self) -> Result<(), InvalidResourceError> {
        let ResourceState::Valid(_) = &self.state else {
            return Err(InvalidResourceError(self.error_ident()));
        };
        Ok(())
    }

    pub(crate) fn invalid(device: Arc<Device>, label: String) -> Arc<Self> {
        Arc::new(Self {
            tracking_data: TrackingData::new(device.tracker_indices.render_pipelines.clone()),
            state: ResourceState::Invalid,
            device,
            _shader_modules: ArrayVec::new(),
            pass_context: RenderPassContext {
                attachments: AttachmentData {
                    colors: ArrayVec::new(),
                    resolves: ArrayVec::new(),
                    depth_stencil: None,
                },
                sample_count: 0,
                multiview_mask: None,
            },
            flags: PipelineFlags::empty(),
            topology: wgt::PrimitiveTopology::TriangleList,
            strip_index_format: None,
            vertex_steps: Vec::new(),
            late_sized_buffer_groups: ArrayVec::new(),
            immediate_slots_required: naga::valid::ImmediateSlots::default(),
            label,
            is_mesh: false,
            has_task_shader: false,
        })
    }

    pub fn get_bind_group_layout_inner(
        self: &Arc<Self>,
        index: u32,
    ) -> Result<Arc<BindGroupLayout>, GetBindGroupLayoutError> {
        self.layout()?.get_bind_group_layout(index, self.into())
    }

    pub fn get_bind_group_layout(self: &Arc<Self>, index: u32) -> Arc<BindGroupLayout> {
        let bgl = self
            .get_bind_group_layout_inner(index)
            .unwrap_or_else(|err| {
                self.device
                    .handle_error_nolabel(err, "RenderPipeline::get_bind_group_layout");
                BindGroupLayout::invalid(&self.device, String::new())
            });
        #[cfg(feature = "trace")]
        if let Some(ref mut trace) = *self.device.trace.lock() {
            use crate::device::trace;

                ),
            )
            .into());
        }
    }

    if !target_specified {
        return Err(pipeline::RenderError::NoTargetSpecified.into());
    }

    let is_auto_layout = desc.layout.is_none();

    // Get the pipeline layout from the desc if it is provided.
    let pipeline_layout = match desc.layout {
        Some(pipeline_layout) => {
            pipeline_layout.same_device(self)?;
            pipeline_layout.check_valid()?;
            Some(pipeline_layout)
        }
        None => None,
    };

    let samples = {
        let sc = desc.multisample.count;
        if sc == 0 || sc > 32 || !sc.is_power_of_two() {
            return Err(pipeline::RenderError::InvalidSampleCount(sc).into());
        }
        sc
    };

    // Validate and compile each programmable shader stage.
    let mut compiler =
        StageCompiler::new(self, pipeline_layout, io, Some(desc.primitive.topology));
    let vertex_stage;
    let task_stage;
    let mesh_stage;

    match desc.vertex {
        pipeline::RenderPipelineVertexProcessor::Vertex(ref vertex) => {
            let stage = validation::ShaderStageForValidation::Vertex {
                topology: desc.primitive.topology,
                compare_function: desc.depth_stencil.as_ref().and_then(|d| d.depth_compare),
            };
            vertex_stage = Some(compiler.compile(&vertex.stage, stage)?);
            task_stage = None;
            mesh_stage = None;
        }
        pipeline::RenderPipelineVertexProcessor::Mesh(ref task, ref mesh) => {
            self.require_features(wgt::Features::EXPERIMENTAL_MESH_SHADER)?;

            vertex_stage = None;
            task_stage = match task {
                Some(task) => Some(
                    compiler
                        .compile(&task.stage, validation::ShaderStageForValidation::Task)?,
                ),
                None => None,
            };
            mesh_stage = Some(
                compiler.compile(&mesh.stage, validation::ShaderStageForValidation::Mesh)?,
            );
        }
    }

    let fragment_stage = match desc.fragment {
        Some(ref fragment) => {
            let stage = validation::ShaderStageForValidation::Fragment {
                dual_source_blending,
                has_depth_attachment,
            };
            Some(compiler.compile(&fragment.stage, stage)?)
        }
        None => None,
    };

    // Extract the information the `StageCompiler` has accumulated about the
    // overall pipeline.
    let StageCompiler {
        resources,
        io,
        validated: validated_stages,
        ..
    } = compiler;

    let mut active_color_outputs = 0u64;
    if validated_stages.contains(wgt::ShaderStages::FRAGMENT) {
        for (i, output) in io.varyings.iter() {
            active_color_outputs |= 1 << i;
            match color_targets.get(*i as usize) {
                Some(Some(state)) => {
                    validation::check_color_attachment_compatibility(state, output.ty)
                        .map_err(|err| pipeline::RenderError::ColorState(*i as u8, err))?;
                }
                _ => {
                    log::debug!(
                        "The fragment stage {:?} output @location({}) values are ignored",
                        fragment_stage
                            .as_ref()
                            .map_or("", |stage| stage.entry_point.as_str()),
                        i
                    );
                }
            }
        }

        let missing_color_outputs = required_color_outputs & !active_color_outputs;
        if missing_color_outputs != 0 {
            return Err(pipeline::RenderError::ColorState(
                missing_color_outputs.trailing_zeros() as u8,
                ColorStateError::OutputNotPresent,
            )
            .into());
        }
    }

    let pipeline_layout = match resources.layout {
        validation::BindingLayoutSource::Provided(pipeline_layout) => pipeline_layout,
        validation::BindingLayoutSource::Derived(entries) => {
            self.create_derived_pipeline_layout(entries, resources.immediates.size())?
        }
    };

    let naga::valid::ImmediateUsage::Valid {
        slots: immediate_slots_required,
        size: _,
    } = resources.immediates
    else {
        unreachable!("Immediates exceeding maxImmediateSize should have been rejected");
    };

    if let pipeline::RenderPipelineVertexProcessor::Vertex(ref vertex) = desc.vertex {
        let bind_groups_plus_vertex_buffers =
            u32::try_from(pipeline_layout.bind_group_layouts.len() + vertex.buffers.len())
                .unwrap();
        if bind_groups_plus_vertex_buffers > self.limits.max_bind_groups_plus_vertex_buffers {
            return Err(pipeline::RenderError::TooManyBindGroupsPlusVertexBuffers {
                given: bind_groups_plus_vertex_buffers,
                limit: self.limits.max_bind_groups_plus_vertex_buffers,
            }
            .into());
        }

        let given = pipeline_layout
            .buffers_and_acceleration_structures_in_vertex_stage
            .saturating_add(vertex.buffers.len() as u32);
        if !self
            .instance_flags
            .contains(wgt::InstanceFlags::STRICT_WEBGPU_COMPLIANCE)
        {
            let limit = self
                .limits
                .max_buffers_and_acceleration_structures_per_shader_stage;
            if given > limit {
                return Err(
                    pipeline::RenderError::TooManyBuffersAndAccelerationStructuresInVertexStage {
                        given,
                        limit,
                    }
                    .into(),
                );
            }
        }
    }

    // Multiview is only supported if the feature is enabled
    if let Some(mv_mask) = desc.multiview_mask {
        self.require_features(wgt::Features::MULTIVIEW)?;
        if !(mv_mask.get() + 1).is_power_of_two() {
            self.require_features(wgt::Features::SELECTIVE_MULTIVIEW)?;
        }
    }

    if !self
        .downlevel
        .flags
        .contains(wgt::DownlevelFlags::BUFFER_BINDINGS_NOT_16_BYTE_ALIGNED)
    {
        for (binding, size) in resources.minimum_binding_sizes.iter() {
            if size.get() % 16 != 0 {
                return Err(pipeline::RenderError::UnalignedShader {
                    binding: binding.binding,
                    group: binding.group,
                    size: size.get(),
                }
                .into());
            }
        }
    }

    let late_sized_buffer_groups = Device::make_late_sized_buffer_groups(
        &resources.minimum_binding_sizes,
        &pipeline_layout,
    );

    let cache = match desc.cache {
        Some(cache) => {
            cache.check_is_valid()?;
            cache.same_device(self)?;
            Some(cache)
        }
        None => None,
    };

    let is_mesh = mesh_stage.is_some();
    let has_task_shader = task_stage.is_some();
    let raw = {
        let pipeline_desc = hal::RenderPipelineDescriptor {
            label: desc.label.to_hal(self.instance_flags),
            layout: pipeline_layout.raw()?,
            vertex_processor: match vertex_stage {
                Some(ref vertex_stage) => hal::VertexProcessor::Standard {
                    vertex_buffers: &hal_vertex_buffer_layouts,
                    vertex_stage: vertex_stage.to_hal(),
                },
                None => hal::VertexProcessor::Mesh {
                    task_stage: task_stage.as_ref().map(|stage| stage.to_hal()),
                    mesh_stage: mesh_stage.as_ref().unwrap().to_hal(),
                },
            },
            primitive: desc.primitive,
            depth_stencil: desc.depth_stencil.clone(),
            multisample: desc.multisample,
            fragment_stage: fragment_stage.as_ref().map(|stage| stage.to_hal()),
            color_targets,
            multiview_mask: desc.multiview_mask,
            cache: cache.as_ref().map(|it| it.raw()).transpose()?,
        };
        unsafe { self.raw().create_render_pipeline(&pipeline_desc) }
            .map_err(|err| self.handle_hal_pipeline_error(err))?
    };
    drop((vertex_stage, task_stage, mesh_stage, fragment_stage));

    let pass_context = RenderPassContext {
        attachments: AttachmentData {
            colors: color_targets
                .iter()
                .map(|state| state.as_ref().map(|s| s.format))
                .collect(),
            resolves: ArrayVec::new(),
            depth_stencil: depth_stencil_state.as_ref().map(|state| state.format),
        },
        sample_count: samples,
        multiview_mask: desc.multiview_mask,
    };

    let mut flags = pipeline::PipelineFlags::empty();
    for state in color_targets.iter().filter_map(|s| s.as_ref()) {
        if let Some(ref bs) = state.blend {
            if bs.color.uses_constant() | bs.alpha.uses_constant() {
                flags |= pipeline::PipelineFlags::BLEND_CONSTANT;
            }
        }
    }
    if let Some(ds) = depth_stencil_state.as_ref() {
        if ds.stencil.is_enabled() && ds.stencil.needs_ref_value() {
            flags |= pipeline::PipelineFlags::STENCIL_REFERENCE;
        }
        if !ds.is_depth_read_only() {
            flags |= pipeline::PipelineFlags::WRITES_DEPTH;
        }
        if !ds.is_stencil_read_only(desc.primitive.cull_mode) {
            flags |= pipeline::PipelineFlags::WRITES_STENCIL;
        }
    }
    let shader_modules = {
        let mut shader_modules = ArrayVec::new();
        match desc.vertex {
            pipeline::RenderPipelineVertexProcessor::Vertex(vertex) => {
                shader_modules.push(vertex.stage.module)
            }
            pipeline::RenderPipelineVertexProcessor::Mesh(task, mesh) => {
                if let Some(task) = task {
                    shader_modules.push(task.stage.module);
                }
                shader_modules.push(mesh.stage.module);
            }
        }
        shader_modules.extend(desc.fragment.map(|f| f.stage.module));
        shader_modules
    };

    let pipeline = pipeline::RenderPipeline {
        state: ResourceState::Valid(pipeline::RenderPipelineState {
            raw: ManuallyDrop::new(raw),
            layout: pipeline_layout.clone(),
        }),
        device: self.clone(),
        pass_context,
        _shader_modules: shader_modules,
        flags,
        topology: desc.primitive.topology,
        strip_index_format: desc.primitive.strip_index_format,
        vertex_steps,
        late_sized_buffer_groups,
        immediate_slots_required,
        label: desc.label.to_string(),
        tracking_data: TrackingData::new(self.tracker_indices.render_pipelines.clone()),
        is_mesh,
        has_task_shader,
    };

    let pipeline = Arc::new(pipeline);

    if is_auto_layout {
        for bgl in pipeline_layout.bind_group_layouts.iter() {
            let Some(bgl) = bgl else {
                continue;
            };

            // `bind_group_layouts` might contain duplicate entries, so we need to ignore the
            // result.
            let _ = bgl.exclusive_pipeline.set((&pipeline).into());
        }
    }

    Ok(pipeline)
}

