    let pipeline = device.create_mesh_pipeline(&wgpu::MeshPipelineDescriptor {
        label: None,
        layout: Some(&layout),
        task: info.use_task.then_some(wgpu::TaskState {
            module: &shader,
            entry_point: Some("ts_main"),
            compilation_options: wgpu::PipelineCompilationOptions::default(),
        }),
        mesh: wgpu::MeshState {
            module: &shader,
            entry_point: Some(if info.divergent && info.use_task {
                "ms_divergent"
            } else if info.use_task {
                "ms_main"
            } else {
                "ms_no_ts"
            }),
            compilation_options: Default::default(),
        },
        fragment: Some(wgpu::FragmentState {
            module: &shader,
            entry_point: Some("fs_main"),
            targets: &[],
            compilation_options: Default::default(),
        }),
        primitive: wgpu::PrimitiveState {
            cull_mode: Some(wgpu::Face::Back),
            ..Default::default()
        },
        depth_stencil: Some(depth_state),
        multisample: Default::default(),
        multiview: None,
        cache: None,
    });
    let buffer = match draw_type {
        DrawType::Standard => None,
        DrawType::Indirect | DrawType::MultiIndirect | DrawType::MultiIndirectCount => Some(
            device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                label: None,
                usage: wgpu::BufferUsages::INDIRECT,
                contents: bytemuck::bytes_of(&[1u32; 4]),
            }),
        ),
    };
    let count_buffer = match draw_type {
        DrawType::MultiIndirectCount => Some(device.create_buffer_init(
            &wgpu::util::BufferInitDescriptor {
                label: None,
                usage: wgpu::BufferUsages::INDIRECT,
                contents: bytemuck::bytes_of(&[1u32; 1]),
            },
        )),
        _ => None,
    };
    let mut encoder =
        device.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: None });
    {
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: None,
            color_attachments: &[],
            depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
                view: &depth_view,
                depth_ops: Some(wgpu::Operations {
                    load: wgpu::LoadOp::Clear(1.0),
                    store: wgpu::StoreOp::Store,
                }),
                stencil_ops: None,
            }),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_pipeline(&pipeline);
        match draw_type {
            DrawType::Standard => pass.draw_mesh_tasks(1, 1, 1),
            DrawType::Indirect => pass.draw_mesh_tasks_indirect(buffer.as_ref().unwrap(), 0),
            DrawType::MultiIndirect => {
                pass.multi_draw_mesh_tasks_indirect(buffer.as_ref().unwrap(), 0, 1)
            }
            DrawType::MultiIndirectCount => pass.multi_draw_mesh_tasks_indirect_count(
                buffer.as_ref().unwrap(),
                0,
                count_buffer.as_ref().unwrap(),
                0,
                1,
            ),
        }
    }
    ctx.queue.submit(Some(encoder.finish()));
    ctx.device
        .poll(wgpu::PollType::wait_indefinitely())
        .unwrap();
}

async fn mesh_multi_draw_indirect_color_readback(ctx: TestingContext) {
    let device = &ctx.device;
    let shader = device.create_shader_module(wgpu::include_wgsl!("shader.wgsl"));
    let layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: None,
        bind_group_layouts: &[],
        immediate_size: 0,
    });
    let pipeline = device.create_mesh_pipeline(&wgpu::MeshPipelineDescriptor {
        label: None,
        layout: Some(&layout),
        task: Some(wgpu::TaskState {
            module: &shader,
            entry_point: Some("ts_main"),
            compilation_options: wgpu::PipelineCompilationOptions::default(),
        }),
        mesh: wgpu::MeshState {
            module: &shader,
            entry_point: Some("ms_main"),
            compilation_options: Default::default(),
        },
        fragment: Some(wgpu::FragmentState {
            module: &shader,
            entry_point: Some("fs_main"),
            targets: &[Some(wgpu::ColorTargetState {
                format: wgpu::TextureFormat::Rgba8Unorm,
                blend: None,
                write_mask: wgpu::ColorWrites::ALL,
            })],
            compilation_options: Default::default(),
        }),
        primitive: wgpu::PrimitiveState {
            cull_mode: Some(wgpu::Face::Back),
            ..Default::default()
        },
        depth_stencil: None,
        multisample: Default::default(),
        multiview: None,
        cache: None,
    });

    // Enough draws to take Metal's ICB path (`ICB_MIN_DRAW_COUNT`).
    let indirect_args = [wgpu::util::DispatchIndirectArgs { x: 1, y: 1, z: 1 }; 512];
    let indirect_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        usage: wgpu::BufferUsages::INDIRECT,
        contents: bytemuck::cast_slice(&indirect_args),
    });

    let texture_size = wgpu::Extent3d {
        width: 64,
        height: 64,
        depth_or_array_layers: 1,
    };
    let texture = device.create_texture(&wgpu::TextureDescriptor {
        label: None,
        size: texture_size,
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: wgpu::TextureFormat::Rgba8Unorm,
        usage: wgpu::TextureUsages::RENDER_ATTACHMENT | wgpu::TextureUsages::COPY_SRC,
        view_formats: &[],
        texture_binding_view_dimension: None,
    });
    let texture_view = texture.create_view(&wgpu::TextureViewDescriptor::default());
    let readback = ReadbackBuffers::new(device, &texture);

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
    {
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: None,
            color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                view: &texture_view,
                resolve_target: None,
                depth_slice: None,
                ops: wgpu::Operations {
                    // Transparent black, so an untouched target reads back as
                    // all zeros and the assertion below cannot pass vacuously.
                    load: wgpu::LoadOp::Clear(wgpu::Color::TRANSPARENT),
                    store: wgpu::StoreOp::Store,
                },
            })],
            depth_stencil_attachment: None,
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_pipeline(&pipeline);
        pass.multi_draw_mesh_tasks_indirect(&indirect_buffer, 0, indirect_args.len() as u32);
    }

    readback.copy_from(device, &mut encoder, &texture);
    ctx.queue.submit([encoder.finish()]);

    assert!(
        !readback.are_zero(&ctx).await,
        "multi_draw_mesh_tasks_indirect should render something over the transparent clear"
    );
}

fn default_gpu_test_config(draw_type: DrawType) -> GpuTestConfiguration {
    let params = TestParameters::default();
    // Metal's shader validation layer (MTL_SHADER_VALIDATION=1, which the
    // harness enables) makes GPU-generated mesh commands in indirect command
    // buffers execute without drawing anything on macOS 26+ / Apple9, and
    // reports nothing; the same commands draw correctly without it. That
    // holds with every inherited bind count at 31 too, so it isn't a bind
    // count the commands read past. Multi-draws can be lowered to ICBs on
    // Metal, so they run without shader validation, as the ray-tracing tests
    // already do.
    let params = match draw_type {
        DrawType::MultiIndirect => params.disable_mtl_shader_validation(),
        DrawType::Standard | DrawType::Indirect | DrawType::MultiIndirectCount => params,
    };
    GpuTestConfiguration::new().parameters(
        params
            .instance_flags(wgpu::InstanceFlags::GPU_BASED_VALIDATION)
            .features(
                wgpu::Features::EXPERIMENTAL_MESH_SHADER
                    | wgpu::Features::PASSTHROUGH_SHADERS
                    | match draw_type {
                        DrawType::Standard | DrawType::Indirect | DrawType::MultiIndirect => {
                            wgpu::Features::empty()
                        }
                        DrawType::MultiIndirectCount => wgpu::Features::MULTI_DRAW_INDIRECT_COUNT,
                    },
            )
            .limits(wgpu::Limits::default().using_recommended_minimum_mesh_shader_values())
            .skip(wgpu_test::FailureCase {
                backends: None,
                // Skip Mesa because LLVMPIPE has what is believed to be a driver bug
                vendor: Some(0x10005),
                adapter: None,
                driver: None,
                reasons: vec![],
                behavior: wgpu_test::FailureBehavior::Ignore,
            }),
    )
}

